import { convertCurrency } from "../src/money.ts";

// Try different rates to find one where computed value < 92.35 but should round to 92.35
// 100 USD -> target EUR should be 92.35 means rate should be 0.9235 (exactly)
// But floating-point multiplication of (100 * 0.9235) might yield 92.34999...

// Test the exact case from the issue
const m = { amount: 100, currency: "USD" };
const rates = { "USD_EUR": 0.9235 };
const result = convertCurrency(m, "EUR", rates);
console.log("100 USD * 0.9235 =", result.amount);
// Math: 100 * 0.9235 = 92.34999999999999 (floating-point)
// Floor: 92.34 (WRONG)
// Round: 92.35 (correct)

// Check actual JS multiplication
const js_result = 100 * 0.9235;
console.log("100 * 0.9235 raw =", js_result);
console.log("js_result.toFixed(20) =", js_result.toFixed(20));

// Try with a Money.amount = 99.99 (simulating parseMoney result)
const m2 = { amount: 99.99, currency: "USD" };
const r2 = convertCurrency(m2, "EUR", rates);
console.log("99.99 USD * 0.9235 =", r2.amount);
const raw2 = 99.99 * 0.9235;
console.log("raw2 =", raw2, "toFixed 20:", raw2.toFixed(20));

